    lines.push("Active calls:");
    for (const c of calls2) {
      lines.push(`  ${c.call_number || "(no #)"} ${c.incident_type || "?"} @ ${c.location_address || "?"} [${c.status || "?"}${c.unit_call_signs ? `, units ${c.unit_call_signs}` : ""}]`);
    }
