    fleet.post("/lifecycle/lease-vs-buy", async (c) => {
      try {
        const body = await c.req.json();
        const purchasePrice = body.purchase_price || 0;
        const leaseMonthly = body.lease_monthly || 0;
        const leaseTerm = body.lease_term_months || 36;
        const residual = body.residual || 0;
        const leaseTotal = leaseMonthly * leaseTerm;
        const buyTotal = purchasePrice - residual;
        return c.json({ lease_total: leaseTotal, buy_total: buyTotal, recommendation: leaseTotal < buyTotal ? "lease" : "buy", savings: Math.abs(leaseTotal - buyTotal) });
      } catch (err2) {
        return c.json({ error: "Failed" }, 500);
      }
    });
