    fleet.post("/financial/depreciation-comparison", async (c) => {
      try {
        const body = await c.req.json();
        const cost = body.purchase_price || 0;
        const salvage = body.salvage_value || 0;
        const life = body.useful_life_years || 5;
        const depreciable = cost - salvage;
        const sl2 = depreciable / life;
        const db2 = cost * (1 - Math.pow(salvage / cost, 1 / life)) / 12;
        return c.json({ straight_line_annual: Math.round(sl2), declining_balance_annual: Math.round(db2 * 12), sum_of_years_first_year: Math.round(depreciable * life / (life * (life + 1) / 2)) });
      } catch (err2) {
        return c.json({ error: "Failed" }, 500);
      }
    });
