    fleet.get("/financial/tax-depreciation/:id", async (c) => {
      try {
        const vehicleId = Number(c.req.param("id"));
        const db2 = getDb(c.env);
        const ca2 = await queryFirst(db2, "SELECT * FROM fleet_capital_assets WHERE vehicle_id = ?", vehicleId);
        if (!ca2) return c.json({ schedules: [] });
        const cost = ca2.capitalized_cost || 0;
        const life = ca2.useful_life_years || 5;
        const bonus = cost * 0.6;
        const remaining = cost - bonus;
        const annual = remaining / life;
        const schedule = [];
        let book = cost;
        for (let i10 = 1; i10 <= life; i10++) {
          const dep = i10 === 1 ? bonus + annual : annual;
          book -= dep;
          schedule.push({ year: i10, depreciation: Math.round(dep), book_value: Math.max(0, Math.round(book)) });
        }
        return c.json({ schedules: schedule, bonus_depreciation: Math.round(bonus) });
      } catch (err2) {
        return c.json({});
      }
    });
