    fleet.post("/data/reconcile-fuel-card", async (c) => {
      try {
        const db2 = getDb(c.env);
        const body = await c.req.json();
        const txns = body.transactions || [];
        let matched = 0, unmatched = 0;
        for (const t of txns) {
          const existing = await queryFirst(db2, "SELECT id FROM fleet_fuel_log WHERE vehicle_id = ? AND fuel_date = ? AND ROUND(total_cost,2) = ROUND(?,2)", t.vehicle_id, t.fuel_date, t.total_cost ?? 0);
          if (existing) {
            matched++;
          } else {
            unmatched++;
          }
        }
        return c.json({ matched, unmatched, total: txns.length });
      } catch (err2) {
        return c.json({ error: "Failed" }, 500);
      }
    });
