        const active = (await queryFirst(db2, "SELECT COUNT(*) as n FROM fleet_vehicles WHERE status = 'in_service' AND archived_at IS NULL"))?.n ?? 0;
        const fuelYtd = await queryFirst(db2, "SELECT COALESCE(SUM(total_cost),0) as cost, COALESCE(SUM(gallons),0) as gallons FROM fleet_fuel_log WHERE fuel_date >= date('now','start of year')");
        const maintYtd = await queryFirst(db2, "SELECT COALESCE(SUM(cost),0) as cost FROM fleet_maintenance WHERE performed_at >= date('now','start of year')");
        const accidents = (await queryFirst(db2, "SELECT COUNT(*) as n FROM fleet_accidents WHERE accident_date >= date('now','start of year')"))?.n ?? 0;
        const inspections2 = await queryFirst(db2, "SELECT SUM(CASE WHEN overall_result='pass' THEN 1 ELSE 0 END) as pass, SUM(CASE WHEN overall_result='fail' THEN 1 ELSE 0 END) as fail FROM fleet_inspections");
        const totalExpenses = (fuelYtd?.cost ?? 0) + (maintYtd?.cost ?? 0);
        return c.json({ total_vehicles: total, active_vehicles: active, readiness_pct: total > 0 ? Math.round(active / total * 100) : 0, fuel_cost_ytd: fuelYtd?.cost ?? 0, fuel_gallons_ytd: fuelYtd?.gallons ?? 0, maintenance_cost_ytd: maintYtd?.cost ?? 0, total_expenses_ytd: totalExpenses, accidents_ytd: accidents, inspection_pass_rate: (inspections2?.pass ?? 0) + (inspections2?.fail ?? 0) > 0 ? Math.round((inspections2?.pass ?? 0) / ((inspections2?.pass ?? 0) + (inspections2?.fail ?? 0)) * 100) : 100 });
