        const q10 = c.req.query();
        const month = q10.month || (/* @__PURE__ */ new Date()).toISOString().slice(0, 7);
        const fuel = await queryFirst(db2, "SELECT COALESCE(SUM(total_cost),0) as cost, COALESCE(SUM(gallons),0) as gallons FROM fleet_fuel_log WHERE strftime('%Y-%m', fuel_date) = ?", month);
        const maint = await queryFirst(db2, "SELECT COALESCE(SUM(cost),0) as cost, COUNT(*) as count FROM fleet_maintenance WHERE strftime('%Y-%m', performed_at) = ?", month);
