    const existingSeqs = new Set(
      (await query(db2, "SELECT seq FROM footage_chunks WHERE request_id=?", rq.id).catch(() => [])).map((r) => r.seq)
    );
    const chRows = await query(
      db2,
      "SELECT DISTINCT channel FROM footage_chunks WHERE request_id=?",
      rq.id
    ).catch(() => []);
