async function loadActive(db2, unitId) {
  const row = await queryFirst(
    db2,
    `SELECT id, trip_type, call_id, anchor_lat, anchor_lng, last_move_at, last_fix_ts
     FROM unit_trips WHERE unit_id = ? AND status = 'active' ORDER BY start_time DESC LIMIT 1`,
    unitId
  );
  if (!row) return null;
  return {
    id: row.id,
    trip_type: row.trip_type,
    call_id: row.call_id,
    anchor_lat: row.anchor_lat,
    anchor_lng: row.anchor_lng,
    last_move_at: epoch2(row.last_move_at),
    last_fix_ts: epoch2(row.last_fix_ts)
  };
}
